(1614311, 217555, 35357, '<td valign="top">Looks like real rain splashes in the real mud puddle!  Nice catch.</td>', 'Looks like real rain splashes in the real mud puddle!  Nice catch.', '2005-08-16 10:22:39.000000', NULL, 1),
(1614312, 217898, 35357, '<td valign="top">Cute shot.  I like the action &amp; framing.  Love the rainsuit.</td>', 'Cute shot.  I like the action & framing.  Love the rainsuit.', '2005-08-16 10:23:27.000000', NULL, 1),
(1614313, 216961, 35357, '<td valign="top">Looks like another wet leaf shot to me.</td>', 'Looks like another wet leaf shot to me.', '2005-08-16 10:23:48.000000', NULL, 1),
