(1614359, 217846, 35357, '<td valign="top">Love the cows &amp; fog, feels wet, but not rainy..</td>', 'Love the cows & fog, feels wet, but not rainy..', '2005-08-16 10:44:06.000000', NULL, 1),
(1614361, 216530, 35357, '<td valign="top">Not much interest for me.</td>', 'Not much interest for me.', '2005-08-16 10:44:37.000000', NULL, 1),
