(1614402, 217927, 6870, '<td valign="top">Nice painterly effect achieved here! Strong composition and good sense of movement and mood. 9</td>', 'Nice painterly effect achieved here! Strong composition and good sense of movement and mood. 9', '2005-08-16 11:04:42.000000', NULL, 1),
(1614403, 215552, 6870, '<td valign="top">Groovy use of color and composition to create a mood. Very lovely work! 10</td>', 'Groovy use of color and composition to create a mood. Very lovely work! 10', '2005-08-16 11:05:33.000000', NULL, 1),
