(1614435, 217402, 2130, '<td valign="top">beautiful...I would have liked it to be more in focus though</td>', 'beautiful...I would have liked it to be more in focus though', '2005-08-16 11:43:59.000000', NULL, 1),
(1614436, 217894, 2130, '<td valign="top">beautiful, the color is amazing...a 10 from me</td>', 'beautiful, the color is amazing...a 10 from me', '2005-08-16 11:44:44.000000', NULL, 1),
