(1614776, 217330, 37444, '<td valign="top">I really love this image and am interested in your post processing.</td>', 'I really love this image and am interested in your post processing.', '2005-08-16 14:05:39.000000', NULL, 1),
(1614778, 217534, 37444, '<td valign="top">Super image - I love it.</td>', 'Super image - I love it.', '2005-08-16 14:06:39.000000', NULL, 1),
