(1618497, 218034, 13602, '<td valign="top">great photo I like it alot!</td>', 'great photo I like it alot!', '2005-08-17 14:11:16.000000', NULL, 1),
(1618510, 216431, 13602, '<td valign="top">verry nice I like it, certainly not an easy thing to catch a window frame so straight.</td>', 'verry nice I like it, certainly not an easy thing to catch a window frame so straight.', '2005-08-17 14:13:33.000000', NULL, 1),
(1618511, 218050, 13602, '<td valign="top">verry nice textures, I like it.</td>', 'verry nice textures, I like it.', '2005-08-17 14:14:14.000000', NULL, 1),
(1618533, 218043, 13602, '<td valign="top">this looks verry good but that black part of it is weird and I don''t understand it''s purpose other than to hide something. I think a 3x2 crop at the top even if you only keep half the umbrella would be much better.</td>', 'this looks verry good but that black part of it is weird and I don''t understand it''s purpose other than to hide something. I think a 3x2 crop at the top even if you only keep half the umbrella would be much better.', '2005-08-17 14:21:55.000000', NULL, 1),
(1618541, 217497, 13602, '<td valign="top">Verry nice, I like it.</td>', 'Verry nice, I like it.', '2005-08-17 14:25:02.000000', NULL, 1),
(1618542, 216104, 13602, '<td valign="top">great one I like it.</td>', 'great one I like it.', '2005-08-17 14:25:24.000000', NULL, 1),
