(1782028, 216724, 12253, '<td valign="top">You can''t be far from a ribbon with shots like these!  Great work.</td>', 'You can''t be far from a ribbon with shots like these!  Great work.', '2005-10-13 13:21:47.000000', NULL, 0),
(1793080, 217330, 41817, '<td valign="top">I strongly disagree with anyone who didn''t rate this 8 or higher.  It''s like looking at a painting. I enjoy the motion of the subjects.  Very appealing.</td>', 'I strongly disagree with anyone who didn''t rate this 8 or higher.  It''s like looking at a painting. I enjoy the motion of the subjects.  Very appealing.', '2005-10-18 15:43:26.000000', NULL, 0),
